#!/usr/bin/env node

import { build } from 'esbuild';
import { existsSync, readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const cliRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const entrypoint = join(cliRoot, 'src', 'product-hook-entrypoint.js');
const output = join(cliRoot, 'src', 'product-hook-entrypoint.bundle.js');

export async function productHookBundleBytes() {
  const result = await build({
    absWorkingDir: cliRoot,
    banner: { js: [
      '// Generated by scripts/build-product-hook-bundle.mjs. Do not edit.',
      "import { createRequire as __pulseCreateRequire } from 'node:module';",
      'const require = __pulseCreateRequire(import.meta.url);',
    ].join('\n') },
    bundle: true,
    charset: 'utf8',
    entryPoints: [entrypoint],
    format: 'esm',
    legalComments: 'none',
    logLevel: 'silent',
    minify: true,
    outfile: output,
    platform: 'node',
    sourcemap: false,
    target: ['node20'],
    treeShaking: true,
    write: false,
  });
  if (result.outputFiles?.length !== 1 || result.outputFiles[0].path !== output) {
    throw new Error('product_hook_bundle_output_invalid');
  }
  return Buffer.from(result.outputFiles[0].contents);
}

export async function buildProductHookBundle({ check = false } = {}) {
  const bytes = await productHookBundleBytes();
  if (check) {
    if (!existsSync(output) || !readFileSync(output).equals(bytes)) {
      throw new Error('product_hook_bundle_stale');
    }
    return output;
  }
  const temporary = `${output}.${process.pid}.new`;
  try {
    writeFileSync(temporary, bytes, { flag: 'wx', mode: 0o644 });
    renameSync(temporary, output);
  } finally {
    rmSync(temporary, { force: true });
  }
  return output;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  await buildProductHookBundle({ check: process.argv.includes('--check') });
}
